import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel: computes C = A * B where A is (M, K) and B is (K, M),
# with K being small ("tall and skinny" case). Each block handles one row
# of A (cached in shared memory) and a chunk of columns of B/C.
cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define MAX_K 128
#define TILE_M 64
#define TILE_N 64
#define THREAD_TILE_M 4
#define THREAD_TILE_N 4
#define VEC 4
#define THREADS_X (TILE_N / THREAD_TILE_N)
#define THREADS_Y (TILE_M / THREAD_TILE_M)
#define NUM_THREADS (THREADS_X * THREADS_Y)
// Tall-and-skinny GEMM: A is (M, K) row-major, B is (K, M) row-major, C = A * B is (M, M).
// K is small and kept fully resident inside the CTA. Threadblock-level tiling over the
// large M dimension (both rows and columns) reduces redundant global memory traffic for
// both A and B tiles, since each tile is now reused by a larger cooperative thread group
// with register-blocked (THREAD_TILE_M x THREAD_TILE_N) accumulation per thread.
__global__ void tall_skinny_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
    extern __shared__ float smem[];
    float* sA = smem;                 // TILE_M x K
    float* sB = smem + TILE_M * K;    // K x TILE_N
    int row_base = blockIdx.x * TILE_M;
    int col_base = blockIdx.y * TILE_N;
    int tid = threadIdx.x;
    int tx = tid % THREADS_X;
    int ty = tid / THREADS_X;
    // Cooperatively load the A tile (TILE_M x K) into shared memory.
    for (int idx = tid; idx < TILE_M * K; idx += NUM_THREADS) {
        int r = idx / K;
        int k = idx % K;
        int global_row = row_base + r;
        sA[r * K + k] = (global_row < M) ? A[global_row * K + k] : 0.0f;
    }
    // Cooperatively load the B tile (K x TILE_N) into shared memory using vectorized loads.
    const int col_groups = TILE_N / VEC;
    for (int idx = tid; idx < K * col_groups; idx += NUM_THREADS) {
        int k = idx / col_groups;
        int cg = idx % col_groups;
        int col = col_base + cg * VEC;
        if (col + VEC - 1 < M) {
            float4 bvec = *reinterpret_cast<const float4*>(&B[k * M + col]);
            sB[k * TILE_N + cg * VEC + 0] = bvec.x;
            sB[k * TILE_N + cg * VEC + 1] = bvec.y;
            sB[k * TILE_N + cg * VEC + 2] = bvec.z;
            sB[k * TILE_N + cg * VEC + 3] = bvec.w;
        } else {
            #pragma unroll
            for (int c = 0; c < VEC; ++c) {
                int cc = col + c;
                sB[k * TILE_N + cg * VEC + c] = (cc < M) ? B[k * M + cc] : 0.0f;
            }
        }
    }
    __syncthreads();
    float acc[THREAD_TILE_M][THREAD_TILE_N];
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_M; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_TILE_N; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    int row_start = ty * THREAD_TILE_M;
    int col_start = tx * THREAD_TILE_N;
    for (int k = 0; k < K; ++k) {
        float4 breg4 = *reinterpret_cast<const float4*>(&sB[k * TILE_N + col_start]);
        float breg[THREAD_TILE_N];
        breg[0] = breg4.x;
        breg[1] = breg4.y;
        breg[2] = breg4.z;
        breg[3] = breg4.w;
        #pragma unroll
        for (int i = 0; i < THREAD_TILE_M; ++i) {
            float aval = sA[(row_start + i) * K + k];
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_N; ++j) {
                acc[i][j] += aval * breg[j];
            }
        }
    }
    #pragma unroll
    for (int i = 0; i < THREAD_TILE_M; ++i) {
        int global_row = row_base + row_start + i;
        if (global_row < M) {
            #pragma unroll
            for (int j = 0; j < THREAD_TILE_N; ++j) {
                int global_col = col_base + col_start + j;
                if (global_col < M) {
                    C[global_row * M + global_col] = acc[i][j];
                }
            }
        }
    }
}
torch::Tensor tall_skinny_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    TORCH_CHECK(B.size(0) == K, "Inner dimensions must match");
    TORCH_CHECK(B.size(1) == M, "Output must be square (M x M) for this kernel");
    TORCH_CHECK(K <= MAX_K, "K too large for shared memory buffer");
    auto C = torch::empty({M, M}, A.options());
    dim3 block(NUM_THREADS);
    dim3 grid((M + TILE_M - 1) / TILE_M, (M + TILE_N - 1) / TILE_N);
    size_t shmem_bytes = (size_t)(TILE_M * K + K * TILE_N) * sizeof(float);
    if (shmem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(tall_skinny_matmul_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)shmem_bytes);
    }
    tall_skinny_matmul_kernel<<<grid, block, shmem_bytes>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );
    return C;
}
"""

