class ModelNew(nn.Module):
    """
    Optimized model using a custom CUDA kernel for the tall-and-skinny
    matrix multiplication C = A * B, where A is (M, K), B is (K, M),
    and K << M.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_fn = tall_skinny_matmul.tall_skinny_matmul_cuda

    def forward(self, A, B):
        A = A.cuda().contiguous()
        B = B.cuda().contiguous()
        return self.matmul_fn(A, B)


